import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"洛伊默·戴维森 (Lorimer Davidson)","description":"","frontmatter":{},"headers":[],"relativePath":"04_people/洛伊默·戴维森.md","filePath":"04_people/洛伊默·戴维森.md"}'),l={name:"04_people/洛伊默·戴维森.md"};function i(d,a,h,n,s,p){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="洛伊默·戴维森-lorimer-davidson" tabindex="-1">洛伊默·戴维森 (Lorimer Davidson) <a class="header-anchor" href="#洛伊默·戴维森-lorimer-davidson" aria-label="Permalink to &quot;洛伊默·戴维森 (Lorimer Davidson)&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>全名</td><td>Lorimer Davidson</td></tr><tr><td>昵称</td><td>大卫（David）</td></tr><tr><td>出生</td><td>1901年</td></tr><tr><td>逝世</td><td>1983年</td></tr><tr><td>职业</td><td>企业家、保险业高管</td></tr><tr><td>公司</td><td><a href="/03_companies/GEICO.html">GEICO</a></td></tr><tr><td>职务</td><td>GEICO 总裁兼 CEO（1958–1970）</td></tr></tbody></table><h2 id="人生故事" tabindex="-1">人生故事 <a class="header-anchor" href="#人生故事" aria-label="Permalink to &quot;人生故事&quot;">​</a></h2><h3 id="与巴菲特的关键相遇" tabindex="-1">与巴菲特的关键相遇 <a class="header-anchor" href="#与巴菲特的关键相遇" aria-label="Permalink to &quot;与巴菲特的关键相遇&quot;">​</a></h3><p>1951年1月的一个周六，21岁的<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>独自来到 <a href="/03_companies/GEICO.html">GEICO</a> 位于华盛顿的总部。那时候巴菲特年仅21岁，刚刚在<a href="/04_people/杰克·伯恩.html">杰克·伯恩</a>的课上听完关于保险行业的介绍，对这家政府雇员保险公司产生了浓厚兴趣。</p><p>让巴菲特意外的是，他在周六找到了时任 GEICO 副总裁的<strong>洛伊默·戴维森</strong>。戴维森没有让这个年轻人吃闭门羹，而是花了大致 <strong>4 个小时</strong>，深入浅出地向巴菲特讲解保险行业的经济学原理——浮存金（float）的概念、保险承保的风险管理、以及 GEICO 的低成本直销模式。</p><p>这次长达4小时的交谈，彻底点燃了巴菲特对保险行业的热情，也为他日后建立伯克希尔·哈撒韦的保险帝国埋下了种子。</p><blockquote><p>巴菲特后来多次公开表示，这次会面改变了他整个投资生涯的方向。</p></blockquote><h3 id="职业生涯" tabindex="-1">职业生涯 <a class="header-anchor" href="#职业生涯" aria-label="Permalink to &quot;职业生涯&quot;">​</a></h3><ul><li>长期担任 GEICO 高管</li><li>1958–1970 年担任 GEICO 总裁兼 CEO</li><li>在他的领导下，GEICO 成长为美国最大的汽车保险公司之一</li></ul><h3 id="与巴菲特的终生友谊" tabindex="-1">与巴菲特的终生友谊 <a class="header-anchor" href="#与巴菲特的终生友谊" aria-label="Permalink to &quot;与巴菲特的终生友谊&quot;">​</a></h3><p>这次相遇不仅开启了巴菲特对保险业的深度理解，也开启了两人之间长达数十年的终生友谊。此后数十年间，戴维森与巴菲特始终保持着密切的联系和深厚的情谊。</p><p>1970年代，GEICO 曾一度陷入严重的承保危机。1976年，公司几乎濒临破产边缘。巴菲特正是在此时大举投资 GEICO，并最终将其纳入<a href="/search.html?q=伯恩">伯恩</a>旗下。这段历史也与<a href="/04_people/托尼·尼斯利.html">托尼·尼斯利</a>在 GEICO 重组中扮演的关键角色密切相关——是尼斯利主导了 GEICO 的重整与复兴。</p><p>从某种意义上说，没有戴维森1951年在那个周六的慷慨分享，就不会有巴菲特后来对 GEICO 数十年如一日的关注与最终收购。</p><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><h3 id="经典语录" tabindex="-1">经典语录 <a class="header-anchor" href="#经典语录" aria-label="Permalink to &quot;经典语录&quot;">​</a></h3><blockquote><p>&quot;我在1951年1月一个周六的下午走进了 GEICO，从此改变了我整个投资生涯的方向。&quot; —— 沃伦·巴菲特</p></blockquote><blockquote><p>&quot;是洛伊默·戴维森让我第一次真正理解了保险行业的经济逻辑——浮存金的价值，以及为什么 GEICO 的商业模式如此了不起。&quot; —— 巴菲特回忆</p></blockquote><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><h3 id="对伯克希尔" tabindex="-1">对伯克希尔 <a class="header-anchor" href="#对伯克希尔" aria-label="Permalink to &quot;对伯克希尔&quot;">​</a></h3><ul><li>启蒙了巴菲特的保险投资理念</li><li>为伯克希尔后来建立的保险帝国奠定了认知基础</li><li>GEICO 最终成为伯克希尔最核心的子公司之一</li></ul><h3 id="对巴菲特个人" tabindex="-1">对巴菲特个人 <a class="header-anchor" href="#对巴菲特个人" aria-label="Permalink to &quot;对巴菲特个人&quot;">​</a></h3><ul><li>建立了巴菲特与 GEICO 之间跨越半个世纪的情缘</li><li>证明了&quot;人生中一次真诚的分享可以改变另一个人的命运轨迹&quot;</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1976, 1985, 1993, 2010</p><hr><p><em>最后更新：2026-04-12</em></p>',28)])])}const m=t(l,[["render",i]]);export{c as __pageData,m as default};
